// Write FTG's email about a client's message on a file: in its chat, or as the
// reason they rejected it. It only ever goes to FTG's own inbox, and anyone can
// call this webhook, so everything taken from the request is escaped here.
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const line = (s, max) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, max);

const b = $input.first().json.body || {};
const message = String(b.message ?? '').trim().slice(0, 4000);
if (!message) throw new Error('No message.');
const email = line(b.client_email, 200);
const who = line(b.client_name, 120) || email || 'A client';
const file = line(b.file_name, 200) || 'a file';
const folder = line(b.folder, 80);
const rejected = b.kind === 'rejected';

const subject = rejected ? `${who} rejected ${file}` : `${who} sent a message about ${file}`;
const html =
  `<p><b>${esc(who)}</b>${email && email !== who ? ' (' + esc(email) + ')' : ''} `
  + (rejected ? 'rejected a file in the FTG portal. Their reason:' : 'sent a message in the FTG portal.') + '</p>'
  + `<p><b>File:</b> ${esc(file)}${folder ? ' <span style="color:#6B5E52">(' + esc(folder) + ')</span>' : ''}</p>`
  + `<div style="margin:12px 0;padding:10px 14px;border-left:3px solid #E8B923;background:#FBF7EE;white-space:pre-wrap">${esc(message)}</div>`
  + `<p>To reply, open the file in <b>Documents</b> and press its chat icon.</p>`
  + `<p><a href="${APP}">Open the portal</a></p>`;

return [{ json: { subject, html } }];
